// Generic "show a message, wait for OK" dialog — used for the multi-select case (D1), where
// there's no resolvable mailbox item to attach a notificationMessages bar to, so
// Office.context.ui.displayDialogAsync is the only way to tell the user anything at all.

Office.onReady(() => {
  const params = new URLSearchParams(window.location.search);
  const message = params.get("message") ?? "";
  const messageEl = document.getElementById("message") as HTMLDivElement;
  messageEl.textContent = message;

  const okButton = document.getElementById("okButton") as HTMLButtonElement;
  okButton.addEventListener("click", () => Office.context.ui.messageParent("ok"));
});
